int target_pid = 0; // Current process
int priority = 4; // Priority 0 (highest) to 7 (lowest)

// I/O Class: Best Effort (BE), typically 2
int class_be = IOPRIO_CLASS_BE; 

// Encode class and priority into the ioprio mask
int ioprio_mask = (class_be << 13) | priority;

// Set priority for the current process
int ret = ioprio_set(IOPRIO_WHO_PROCESS, target_pid, ioprio_mask);

if (ret == -1) {
    // Failure (e.g., EPERM, EINVAL)
}
